/**
 * dsh-provider-usage — unit：内置 DeepSeek 官方适配器（issue #198）。
 *
 * 覆盖（对照验收清单分组）：
 * - B 组：取数归一化 / 多币种过滤 / 无 CNY 修订版行为 / 错误码 / 请求形态
 * - C 组：区间记账分类（clean/disturbed/unavailable）+ 降幅口径 + is_available=false 端点策略
 * - E 组：三级密钥链（显式注入 → V1 链 env 推导 → DEEPSEEK_API_KEY 自查兜底）
 * - G 组：峰谷时段常量 / 半开区间 / 周末全谷 / 倒计时单调与钳制 / 徽标渲染
 * - K 组：原型对齐断言（严格解析 / 端点剥离 / 六态错误路径 / GAP 判定 / 分层渲染 /
 *   时区口径 / skipFirst / 面板结构 / 胶囊文案）
 *
 * 纪律：全程无网络（fetch 全部 mock 注入）；无真实凭据（env 用例 try/finally 恢复）；
 * 峰谷判定与倒计时全部以 timestamp 入参注入固定 epoch，判定路径无墙钟调用（T3）。
 */
console.error("EVAL-ORDER-TAG: DS-OFFICIAL");
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";
import { mkdtempSync } from "node:fs";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
// 白盒直连深路径（#768 B波）：日界纯面经 shared 门面，不走组合根转发。
import { dayKey } from "../../../src/shared/interface.ts";
// 白盒直连深路径（#768 B波）：契约/净化纯面经 shared 门面，不走组合根转发。
import { esc, sanitizeHtml, isUsageStatsAdapter } from "../../../src/shared/interface.ts";
import { runV2Pipeline } from "../../../src/server/pipeline/interface.ts";
import { resolveProviderConfig } from "../../../src/server/registry/interface.ts";
// 白盒直连深路径（#768 B波）：适配器纯面经 server/adapters 门面，不走组合根转发。
import type { SamplePoint, DayRecord } from "../../../src/server/adapters/interface.ts";
import type { FetchContext, PanelInput } from "../../../src/shared/interface.ts";
import type { V2PipelineResult } from "../../../src/server/pipeline/interface.ts";
import {
  DEEPSEEK_OFFICIAL_ADAPTER_ID,
  DEEPSEEK_OFFICIAL_PROVIDER,
  OPENCODE_GO_ADAPTER_ID,
  openCodeGoAdapter,
  deepSeekOfficialAdapter,
  PEAK_WINDOWS_UTC,
  PEAK_LOOKAHEAD_DAYS,
  CHINA_PUBLIC_HOLIDAYS_UTC,
  utcDateKey,
  isHolidayUtc,
  isPeakUtc,
  nextPeakTransition,
  peakBadgeHtml,
  parseAmount,
  resolveEndpoint,
  classifyIntervalDs,
  aggregateDaily,
  lastNDayKeys,
  niceCeil,
  TOL,
  ANOMALY_NEG,
  dailyBarTitle,
} from "../../../src/server/adapters/interface.ts";

const here = dirname(fileURLToPath(import.meta.url));

// ---------------------------------------------------------------- 时间戳辅助（固定 epoch，T3）

/** UTC 时间戳便捷构造（月份 1–12）。 */
const utc = (y: number, mo: number, d: number, hh: number, mi: number, ss = 0, ms = 0): number =>
  Date.UTC(y, mo - 1, d, hh, mi, ss, ms);
// 2026-08-24 为周一（24/25/26/27/28 = 一至五；29/30 = 六/日）
const MON = (hh: number, mi: number, ss = 0, ms = 0): number => utc(2026, 8, 24, hh, mi, ss, ms);
const SAT = (hh: number, mi: number, ss = 0, ms = 0): number => utc(2026, 8, 29, hh, mi, ss, ms);
const SUN = (hh: number, mi: number, ss = 0, ms = 0): number => utc(2026, 8, 30, hh, mi, ss, ms);

/** 构造 mock Response（官方文档示例 JSON 形态蓝本）。 */
function mockRes(status: number, body: unknown) {
  return {
    status,
    ok: status >= 200 && status < 300,
    json: async () => body,
  } as unknown as Response;
}

/** 构造官方 balance 响应体。 */
function officialBody(
  cny: Record<string, unknown> = {},
  extraInfos: Array<Record<string, unknown>> = [],
  isAvailable = true,
) {
  return {
    is_available: isAvailable,
    balance_infos: [
      {
        currency: "CNY",
        total_balance: "110.00",
        topped_up_balance: "90.00",
        granted_balance: "20.00",
        ...cny,
      },
      ...extraInfos,
    ],
  };
}

/** 捕获请求形态的 mock fetch。 */
function capturingFetch(res: unknown) {
  const calls: Array<{ url: string; init: { headers: Record<string, string> } }> = [];
  const f = (url: unknown, init: { headers: Record<string, string> }) => {
    calls.push({ url: String(url), init });
    return Promise.resolve(
      typeof res === "function" ? (res as (u: unknown, i: unknown) => unknown)(url, init) : res,
    );
  };
  return { f: f as unknown as typeof fetch, calls };
}

/** 捕获 rejection 的 error 对象（未 reject 时返回 undefined，断言随即 fail-loud）。 */
async function catchErr(
  p: Promise<unknown>,
): Promise<{ message?: unknown; name?: unknown } | undefined> {
  try {
    await p;
    return undefined;
  } catch (e) {
    return e as { message?: unknown; name?: unknown };
  }
}

/** 适配器直调 ctx：fetch 直注（v2 管线外直调形态，fetchDeepSeekOfficialV2 声明面同款）。
 * 恒等函数——只做类型面收敛（多余字段仍红），运行时零变化。 */
type AdapterFetchCtx = FetchContext & { fetch?: typeof fetch };
const adapterCtx = (ctx: AdapterFetchCtx): AdapterFetchCtx => ctx;
/** 旧分片兼容点列：available 缺省视为可用（实现注释口径），窄类型经 unknown 断言。 */
const ptsOf = (points: Array<Record<string, unknown>>): SamplePoint[] =>
  points as unknown as SamplePoint[];
const fetchCtx = (over: Partial<AdapterFetchCtx> = {}): AdapterFetchCtx => ({
  apiEndpoint: "",
  staticPath: "",
  apiKey: "sk-unit",
  provider: DEEPSEEK_OFFICIAL_PROVIDER,
  timeoutMs: 2000,
  ...over,
});

// ================================================================ B1 + 契约自检

describe("B1 + 契约自检", () => {
  it("内置 DeepSeek 适配器通过 v2 契约校验", () => {
    expect(isUsageStatsAdapter(deepSeekOfficialAdapter)).toBe(true);
  });

  it("适配器 name === DEEPSEEK_OFFICIAL_ADAPTER_ID 常量", () => {
    expect(deepSeekOfficialAdapter.name).toBe(DEEPSEEK_OFFICIAL_ADAPTER_ID);
  });

  it("name 加 -builtin 后缀（有意差异 K12）", () => {
    expect(deepSeekOfficialAdapter.name).toBe("deepseek-official-builtin");
  });

  it("version===2", () => {
    expect(deepSeekOfficialAdapter.version).toBe(2);
  });

  it("认领 deepseek-official provider", () => {
    expect(deepSeekOfficialAdapter.providers).toEqual(["deepseek-official"]);
  });

  it("fetchData 为函数", () => {
    expect(typeof deepSeekOfficialAdapter.fetchData).toBe("function");
  });

  it("formatCapsule 为函数", () => {
    expect(typeof deepSeekOfficialAdapter.formatCapsule).toBe("function");
  });

  it("formatPanel 为函数", () => {
    expect(typeof deepSeekOfficialAdapter.formatPanel).toBe("function");
  });
});

// ================================================================ B2/K1 余额解析 + 归一化输出

describe("B2/K1 余额解析 + 归一化输出", () => {
  let out: Record<string, unknown>;
  let calls: Array<{ url: string; init: { headers: Record<string, string> } }>;

  beforeAll(async () => {
    const captured = capturingFetch(mockRes(200, officialBody()));
    calls = captured.calls;
    out = await deepSeekOfficialAdapter.fetchData(
      adapterCtx({
        apiEndpoint: "https://api.deepseek.com",
        staticPath: "",
        apiKey: "sk-unit",
        provider: DEEPSEEK_OFFICIAL_PROVIDER,
        timeoutMs: 2000,
        fetch: captured.f,
      }),
    );
  });

  it("isAvailable 透传为 true", () => {
    expect(out.isAvailable).toBe(true);
  });

  it('total_balance:"110.00" → 数值 110', () => {
    expect(out.balance).toBe(110);
  });

  it('topped_up_balance:"90.00" → 数值 90', () => {
    expect(out.toppedUp).toBe(90);
  });

  it('granted_balance:"20.00" → 数值 20', () => {
    expect(out.grantedBalance).toBe(20);
  });

  // B6 请求形态：Bearer 密钥在头里，URL 与查询串不含密钥
  it("Authorization: Bearer <key>", () => {
    expect(calls[0].init.headers.Authorization).toMatch(/^Bearer sk-unit$/);
  });

  it("URL 不携带密钥", () => {
    expect(!String(calls[0].url).includes("sk-unit")).toBeTruthy();
  });

  it("Accept: application/json", () => {
    expect(calls[0].init.headers.Accept).toBe("application/json");
  });
});

describe("B2 金额非法形态 → null（杜绝 NaN 落盘）", () => {
  let out: Record<string, unknown>;

  beforeAll(async () => {
    // 金额非法形态 → null（杜绝 NaN 落盘）
    const { f } = capturingFetch(
      mockRes(
        200,
        officialBody({ total_balance: "abc", topped_up_balance: "", granted_balance: undefined }),
