/** 旧门面判据：旧 domain2/collect 长路径或 ../../server/ 非规范深路径残留即红（针脚为域事实，命中循环见 helpers）。同级短径 ../collect/ 为新规（#768 跨域路径统一）。 */
function usesOldFace(src: string): boolean {
